(()=>{'use strict';
const $=s=>document.querySelector(s),M=OCModel,escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),date=s=>new Date(s).toLocaleString('zh-CN',{hour12:false}),short=s=>new Date(s).toLocaleDateString('zh-CN');
let projects=[],project=null,tab='overview',entityId='',online=false,busy=false,dialogSave=null,polling=false,stopped=false;
const notice=text=>{$('#notice').textContent=text;};
function theme(value){value=['sage','ember','crimson','sky'].includes(value)?value:'ember';document.documentElement.dataset.theme=value;document.querySelectorAll('[data-palette]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.palette===value)));try{localStorage.setItem('william-palette',value);}catch{}}
try{theme(localStorage.getItem('william-palette'));}catch{theme('ember');}document.querySelectorAll('[data-palette]').forEach(b=>b.addEventListener('click',()=>theme(b.dataset.palette)));
async function api(path='',method='GET',body){const res=await fetch('/api/oc/projects'+path,{method,headers:{'X-William-Local':'1',...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined,cache:'no-store'});if(!res.headers.get('content-type')?.includes('application/json'))throw new Error('请用项目中的 start-local.cmd 启动本机服务，再打开此页。');const data=await res.json();if(!res.ok){const e=new Error(data.error||'保存失败，请重试');e.status=res.status;throw e;}return data;}
function fail(e){notice(e.message||'暂时无法连接档案库，请检查本机服务。');}
async function refresh(){const result=await api();projects=result.projects;online=true;$('#connection').textContent='本机档案库 · 已连接';renderList();}
function renderList(){const search=$('#project-search').value.trim().toLowerCase(),stage=$('#stage-filter').value,category=$('#category-filter').value;const categories=[...new Set(projects.map(p=>p.category))].sort();$('#category-filter').innerHTML='<option value="">全部分类</option>'+categories.map(c=>`<option ${c===category?'selected':''}>${escape(c)}</option>`).join('');const result=projects.filter(p=>(!stage||p.stage===stage)&&(!category||p.category===category)&&(!search||[p.title,p.summary,p.category,...p.tags].join(' ').toLowerCase().includes(search))).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));$('#project-list').innerHTML=result.map(p=>`<button class="project-link ${project?.id===p.id?'selected':''}" data-project="${escape(p.id)}" ${project?.id===p.id?'aria-current="page"':''}><b>${escape(p.title)}</b><small><span>${escape(p.category)}</span><span>${p.stage==='archived'?'已归档':p.percent+'% 已确定'}</span></small></button>`).join('')||'<p class="help-note">'+(projects.length?'没有符合筛选的档案。':'还没有设计项目。')+'</p>';}
async function select(id){if(busy)return;try{const data=await api('/'+encodeURIComponent(id));project=data.project;tab='overview';entityId='';notice('');render();renderList();}catch(e){fail(e);}}
async function update(operations,note){if(busy)throw new Error('正在保存，请稍候');busy=true;try{const data=await api('/'+project.id,'PATCH',{expectedRevision:project.revision,requestId:crypto.randomUUID(),source:'档案馆手动编辑',note,operations});project=data.project;await refresh().catch(()=>{});render();notice('已保存 · '+date(project.updatedAt));return data;}catch(e){if(e.status===409){const current=await api('/'+project.id).catch(()=>null);if(current){project=current.project;render();}e.message+='。你的输入仍保留在编辑框，请核对最新内容后再保存。';}throw e;}finally{busy=false;}}
const status=f=>`<span class="status ${f.status}">${M.statuses[f.status]}</span>`;
const editable=()=>project?.stage!=='archived';
function cards(entities){return '<div class="entity-grid">'+entities.map((e,index)=>{const s=M.stats({entities:[e]});return `<article class="entity-card"><div class="entity-cover">${e.image?`<img src="${escape(e.image)}" alt="${escape(e.name)}的参考图" loading="lazy" referrerpolicy="no-referrer">`:`<small>${e.kind==='world'?'WORLD ATLAS':e.kind==='character'?'CHARACTER STUDY':'EVENT RECORD'} / ${String(index+1).padStart(2,'0')}</small><span class="monogram" aria-hidden="true">${escape(Array.from(e.name)[0])}</span>`}</div><div class="entity-card-content"><span class="eyebrow">${M.kinds[e.kind]}</span><h4>${escape(e.name)}</h4><p>${escape(e.summary||'轮廓从这里开始，等待更多细节。')}</p><div class="card-foot"><span>${s.confirmed} / ${s.fields} 项已确定</span><span>${s.percent}%</span></div><div class="meter" style="--progress:${s.percent}%"><i></i></div><button data-action="entity" data-id="${escape(e.id)}">展开档案 ↗</button></div></article>`;}).join('')+'</div>';}
function render(){if(!project){$('#empty-state').hidden=false;$('#project-content').hidden=true;return;}$('#empty-state').hidden=true;const el=$('#project-content');el.hidden=false;const p=project,s=M.stats(p);const link=new URL(location.href);link.searchParams.set('project',p.id);history.replaceState(null,'',link);el.innerHTML=`<div class="project-topline"><span>${escape(p.category)} / ${p.stage==='archived'?'ARCHIVED · 已归档':'IN PROGRESS · 正在设计'}</span><span>修订 ${p.revision} · ${short(p.updatedAt)}</span></div><h2 class="project-title">${escape(p.title)}</h2><p class="project-summary">${escape(p.summary||'还没有写下这个设计的概况。')}</p><div class="tags">${p.tags.map(t=>`<span class="tag">${escape(t)}</span>`).join('')}</div><div class="toolbar">${editable()?'<button data-action="edit-project">编辑概况</button><button data-action="save-version">保存设计版本</button><button data-action="archive">归档设计</button>':'<button data-action="restore">恢复设计</button>'}<button data-action="export">导出备份</button><button data-action="markdown">导出阅读版</button><button data-action="connect">AI 编辑接入 ↗</button></div><div class="stats"><div class="stat"><b>${s.percent}<small style="font-size:13px">%</small></b><span>设定已确定 · ${s.confirmed} / ${s.fields}</span><div class="meter" style="--progress:${s.percent}%"><i></i></div></div><div class="stat"><b>${s.characters.toString().padStart(2,'0')}</b><span>角色档案</span></div><div class="stat"><b>${s.tentative.toString().padStart(2,'0')}</b><span>讨论中设定</span></div><div class="stat"><b>${s.open.toString().padStart(2,'0')}</b><span>待补充设定</span></div></div><nav class="tabs" aria-label="档案视图">${Object.entries({overview:'设计总览',world:'世界观',character:'角色',event:'特别事件',versions:'设计版本',history:'修改记录'}).map(([key,label])=>`<button data-tab="${key}" aria-current="${tab===key}">${label}</button>`).join('')}</nav><div id="tab-content"></div>`;renderTab();}
function renderTab(){const p=project,out=$('#tab-content');if(tab==='overview'){const pending=p.entities.flatMap(e=>e.fields.filter(f=>f.status!=='confirmed').map(f=>({e,f})));out.innerHTML=`<div class="section-heading"><h3>这个世界的组成</h3><small>${p.entities.length} 份关联档案</small></div>${cards(p.entities)}<div class="section-heading"><h3>下一步，可以继续敲定</h3><small>讨论中 ${pending.filter(x=>x.f.status==='tentative').length} · 待补充 ${pending.filter(x=>x.f.status==='open').length}</small></div>${pending.length?'<div class="pending-list">'+pending.sort((a,b)=>(a.f.status==='tentative'?0:1)-(b.f.status==='tentative'?0:1)).slice(0,12).map(({e,f})=>`<button class="pending-item" data-action="field" data-entity="${escape(e.id)}" data-id="${escape(f.id)}"><span>${escape(f.label)} <small> / ${escape(e.name)}</small></span>${status(f)}</button>`).join('')+'</div>':'<p class="empty-inline">目前的设定都已确定。你仍可以添加新的角色、事件或细节。</p>'}<p class="help-note">确定比例只统计当前已建条目，不代表整个世界已经设计完毕。总览显示前 12 条未定设定，完整内容可在各份档案中查看。</p>`;return;}
if(['world','character','event'].includes(tab)){const entries=p.entities.filter(e=>e.kind===tab),e=entries.find(e=>e.id===entityId);out.innerHTML=`<div class="section-heading"><h3>${M.kinds[tab]}档案 <small> / ${entries.length}</small></h3>${editable()?`<button class="text-button" data-action="add-entity" data-kind="${tab}">新增${M.kinds[tab]} ＋</button>`:''}</div>`;if(!e){out.innerHTML+=entries.length?cards(entries):`<p class="empty-inline">还没有${M.kinds[tab]}档案。${editable()?'点击右上角，写下第一份。':''}</p>`;return;}out.innerHTML+=`<button class="text-button" data-action="back-entities">← 全部${M.kinds[tab]}</button><div class="detail-heading">${e.image?`<img src="${escape(e.image)}" alt="${escape(e.name)}的参考图" referrerpolicy="no-referrer">`:''}<div><span class="eyebrow">${M.kinds[e.kind]}</span><h3>${escape(e.name)}</h3><p>${escape(e.summary||'概况待补充')}</p></div>${editable()?`<button data-action="edit-entity" data-id="${escape(e.id)}">编辑概况与参考图</button>`:''}</div>${e.links.length?`<div class="linked"><span class="help-note">关联档案</span>${e.links.map(id=>p.entities.find(x=>x.id===id)).filter(Boolean).map(x=>`<button data-action="entity" data-id="${escape(x.id)}">${escape(x.name)} ↗</button>`).join('')}</div>`:''}<div class="field-grid">${e.fields.map(f=>`<article class="field-card"><div class="field-head"><h4>${escape(f.label)}</h4>${status(f)}</div><p class="field-value ${!f.value?'missing':''}">${escape(f.value||'还没有留下这项设定。')}</p>${f.evidence?`<blockquote>确认依据：${escape(f.evidence)}</blockquote>`:''}${f.source?`<p class="source">来源：${escape(f.source)}</p>`:''}${editable()?`<button data-action="field" data-entity="${escape(e.id)}" data-id="${escape(f.id)}">编辑设定</button>`:''}</article>`).join('')}</div>${editable()?`<div class="section-heading"><button class="text-button" data-action="add-field" data-id="${escape(e.id)}">新增自定义设定 ＋</button></div>`:''}`;return;}
if(tab==='history'){out.innerHTML='<p class="help-note">记录最近 500 批修改。AI 确认的设定还会在条目中保留确认依据与来源。</p><div class="timeline">'+p.history.map(h=>`<article><time>${date(h.at)} · ${h.actor==='agent'?'AI 更新':'手动编辑'}</time><h4>${escape(h.note)}</h4><p>${h.changes.map(escape).join('\n')}</p>${h.source?`<p>来源：${escape(h.source)}</p>`:''}</article>`).join('')+'</div>'+(p.history.length?'':'<p class="empty-inline">还没有修改记录，新的设定会从这里留下足迹。</p>');return;}
out.innerHTML='<p class="help-note">保存某个阶段的完整设定，之后仍能继续设计。归档会自动保存一份定稿。导入旧版本时会另存为新项目。</p>'+[...p.versions].reverse().map(v=>`<article class="version-row"><div><h4>${escape(v.name)}</h4><p>${date(v.createdAt)} · 基于修订 ${v.revision}</p></div><button data-action="version" data-id="${escape(v.id)}">查看版本 ↗</button></article>`).join('')+(p.versions.length?'':'<p class="empty-inline">还没有保存版本。可以在完成一轮讨论后，保存一个设计阶段。</p>');}
function field(label,name,value='',type='input',extra=''){return `<label>${label}${type==='textarea'?`<textarea name="${name}" ${extra}>${escape(value)}</textarea>`:`<input name="${name}" value="${escape(value)}" ${extra}>`}</label>`;}
function openDialog(title,body,save,label='保存'){dialogSave=save;$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=body;$('#dialog-error').textContent='';$('#save-dialog').hidden=!save;$('#save-dialog').textContent=label;$('#cancel-dialog').textContent=save?'取消':'关闭';$('#editor').showModal();}
function closeDialog(){$('#editor').close();dialogSave=null;$('#dialog-body').replaceChildren();}
$('#close-dialog').addEventListener('click',closeDialog);$('#cancel-dialog').addEventListener('click',closeDialog);$('#editor').addEventListener('cancel',()=>{dialogSave=null;$('#dialog-body').replaceChildren();});
$('#editor-form').addEventListener('submit',async e=>{e.preventDefault();if(!dialogSave)return;$('#save-dialog').disabled=true;try{await dialogSave(new FormData(e.target));closeDialog();}catch(e){$('#dialog-error').textContent=e.message;}finally{$('#save-dialog').disabled=false;}});
function newProject(){if(!online)return fail(new Error('请先启动本机服务：运行项目中的 start-local.cmd。'));openDialog('新建一个设计项目',field('项目名称','title','','input','required maxlength="160" placeholder="这个世界，叫什么？"')+field('分类','category','','input','maxlength="80" placeholder="例如：奇幻 / 科幻 / 现代"')+field('概况','summary','','textarea','maxlength="3000" placeholder="用几句话，留下最初的方向。"'),async f=>{const data=await api('','POST',{title:f.get('title'),category:f.get('category')||'未分类',summary:f.get('summary')});project=data.project;tab='overview';entityId='';$('#stage-filter').value='draft';$('#category-filter').value='';$('#project-search').value='';await refresh();render();notice('设计项目已创建。可以先补充世界观，或新增角色与事件。');},'创建设计');}
function download(data,name,type='application/json'){const url=URL.createObjectURL(new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type})),a=document.createElement('a');a.href=url;a.download=name.replace(/[<>:"/\\|?*]/g,'_');a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportDoc(p){return {format:'william-oc-archive',version:1,exportedAt:new Date().toISOString(),project:p};}
function markdown(p){return `# ${p.title}\n\n${p.summary}\n\n分类：${p.category}\n\n`+p.entities.map(e=>`## ${M.kinds[e.kind]} · ${e.name}\n\n${e.summary}\n\n`+e.fields.map(f=>`### ${f.label} · ${M.statuses[f.status]}\n\n${f.value||'待补充'}\n\n${f.evidence?'确认依据：'+f.evidence+'\n\n':''}${f.source?'来源：'+f.source+'\n\n':''}`).join('')).join('\n');}
function handoff(token){return `请在我们的 OC 讨论中及时更新以下档案。\n\n接口：${location.origin}/api/oc/projects/${project.id}\n授权请求头：Authorization: Bearer ${token}\n协议说明：GET ${location.origin}/api/oc/guide\n\n每轮先GET读取现有档案和revision，按协议PATCH写入（expectedRevision、requestId、source、operations）。字段与档案使用GET返回的id。用户明确确认才标记confirmed，附evidence确认原话和source对话链接或名称+日期；未定方案用tentative，未知保持open。不虚构、不擅自归档。409时重新读取核对。保存后报告实际成功结果，不把口头答应当成保存。\n\n本机服务需要保持运行。地址只适用于同一台电脑上能发HTTP请求的AI工具；普通ChatGPT网页对话不能仅凭这段文字连接本机。密钥只授权本项目，请勿公开或放入代码仓库。`;
}
async function connect(){openDialog('让讨论与档案接上',`<p class="api-warning">本机试用：适用于这台电脑上的 Codex 会话。仅发送网页链接不能授予编辑能力。ChatGPT 网页／手机接入需要另行部署线上服务并连接编辑工具。</p><p class="help-note">项目密钥只授权这一份设计。生成后仅显示一次；再次生成会让旧密钥失效。接入说明包含密钥，请只交给你信任的会话。</p><div class="row-actions"><button type="button" id="generate-key">生成接入说明</button><button type="button" id="revoke-key">撤销现有 AI 授权</button></div><div id="handoff"></div><details><summary>接口如何更新档案？</summary><p class="help-note">GET 读取；PATCH 提交一批修改。保存采用版本检查，冲突返回 409。AI 标记已确定的条目必须有确认依据与讨论来源。</p><pre>${escape(`GET ${location.origin}/api/oc/guide\nGET ${location.origin}/api/oc/projects/${project.id}\nPATCH 同一项目地址\nAuthorization: Bearer <项目密钥>\nContent-Type: application/json\n\n${JSON.stringify({expectedRevision:project.revision,requestId:'每批唯一的请求标识',source:'对话名称 / 日期',operations:[{op:'entity.add',kind:'character',name:'用户指定的角色名'}]},null,2)}`)}</pre></details>`,null);$('#generate-key').addEventListener('click',async()=>{const b=$('#generate-key');b.disabled=true;try{const {token}=await api('/'+project.id+'/key','POST',{});const text=handoff(token);$('#handoff').innerHTML='<p class="help-note">说明已生成。复制后即可交给本机的其他 Codex 会话。</p><pre id="handoff-text"></pre><button type="button" id="copy-handoff">复制接入说明</button>';$('#handoff-text').textContent=text;$('#copy-handoff').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(text);$('#copy-handoff').textContent='已复制';}catch{$('#copy-handoff').textContent='请选中上面的文字复制';}});b.textContent='重新生成（旧密钥将失效）';}catch(e){$('#dialog-error').textContent=e.message;}finally{b.disabled=false;}});$('#revoke-key').addEventListener('click',async()=>{try{await api('/'+project.id+'/key','DELETE');$('#handoff').innerHTML='<p class="help-note">此项目的 AI 授权已撤销。</p>';}catch(e){$('#dialog-error').textContent=e.message;}});}
async function action(name,node){const id=node?.dataset.id,e=project?.entities.find(x=>x.id===(node?.dataset.entity||id));switch(name){case 'new':return newProject();case 'entity':entityId=id;tab=project.entities.find(x=>x.id===id).kind;render();return;case 'back-entities':entityId='';renderTab();return;
case 'edit-project':return openDialog('编辑设计概况',field('项目名称','title',project.title,'input','required maxlength="160"')+field('分类','category',project.category,'input','maxlength="80"')+field('标签（用逗号分隔）','tags',project.tags.join('，'),'input','maxlength="800"')+field('概况','summary',project.summary,'textarea','maxlength="3000"'),f=>update([{op:'project.update',title:f.get('title'),category:f.get('category')||'未分类',summary:f.get('summary'),tags:f.get('tags').split(/[,，]/).map(s=>s.trim()).filter(Boolean)}]));
case 'add-entity':return openDialog('新增'+M.kinds[node.dataset.kind]+'档案',field('名称','name','','input','required maxlength="160"'),async f=>{await update([{op:'entity.add',kind:node.dataset.kind,name:f.get('name')}]);entityId=project.entities.at(-1).id;render();});
case 'edit-entity':openDialog('编辑'+M.kinds[e.kind]+'概况',field('名称','name',e.name,'input','required maxlength="160"')+field('概况','summary',e.summary,'textarea','maxlength="4000"')+field('参考图网址（可选）','image',e.image.startsWith('data:')?'':e.image,'input','type="url" placeholder="https://…"')+'<label>或上传参考图（不超过 2 MB）<input type="file" name="imageFile" accept="image/png,image/jpeg,image/webp,image/gif"></label><p class="help-note">参考图保存在档案正文里；外部图片会由浏览器直接加载。未更换图片时保留现有图片。</p><label class="checkboxes"><span><input name="removeImage" type="checkbox"> 移除现有参考图</span></label><div class="checkboxes"><span class="help-note">关联角色、世界或事件</span>'+project.entities.filter(x=>x.id!==e.id).map(x=>`<label><input type="checkbox" name="links" value="${escape(x.id)}" ${e.links.includes(x.id)?'checked':''}>${escape(x.name)}</label>`).join('')+'</div>',async f=>{let image=e.image;const file=f.get('imageFile');if(f.get('removeImage'))image='';else if(file?.size){if(file.size>2*1024*1024||!['image/png','image/jpeg','image/webp','image/gif'].includes(file.type))throw new Error('请选择不超过2MB的PNG/JPEG/WebP/GIF图片');image=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(new Error('无法读取图片'));r.readAsDataURL(file);});}else if(f.get('image'))image=f.get('image');await update([{op:'entity.update',entityId:e.id,name:f.get('name'),summary:f.get('summary'),image,links:f.getAll('links')}]);});return;
case 'field':{const f=e.fields.find(x=>x.id===id);if(!editable())return openDialog(f.label,`<p class="help-note">${escape(e.name)} · 已归档，只读</p><p style="white-space:pre-wrap">${escape(f.value||'待补充')}</p>${status(f)}`,null);return openDialog(e.name+' / '+f.label,field('设定内容','value',f.value,'textarea','maxlength="12000"')+`<label>确定程度<select name="status">${Object.entries(M.statuses).map(([k,v])=>`<option value="${k}" ${f.status===k?'selected':''}>${v}</option>`).join('')}</select></label>`+field('确认依据（建议保留确认原话）','evidence',f.evidence,'textarea','maxlength="3000"')+field('讨论来源（对话名称、日期或链接）','source',f.source,'input','maxlength="2000"'),data=>update([{op:'field.set',entityId:e.id,fieldId:f.id,value:data.get('value'),status:data.get('status'),evidence:data.get('evidence'),source:data.get('source')}]));}
case 'add-field':return openDialog('新增自定义设定',field('设定名称','label','','input','required maxlength="120"'),f=>update([{op:'field.add',entityId:e.id,label:f.get('label')}]));
case 'save-version':return openDialog('保存这一阶段的设计',field('版本名称','name','','input','required maxlength="160" placeholder="例如：人物轮廓第一版"')+'<p class="help-note">这会保存当前的完整设定，之后的修改不会改变这个版本。</p>',f=>update([{op:'snapshot',name:f.get('name')}]));
case 'archive':return openDialog('将这份设计归档',field('定稿名称','name','归档定稿','input','required maxlength="160"')+'<p class="help-note">会保存一份完整设计版本，并将项目设为只读。之后可随时恢复设计；未定条目也会如实保留。</p>',async f=>{await update([{op:'archive',name:f.get('name')}]);$('#stage-filter').value='archived';renderList();},'保存并归档');
case 'restore':await update([{op:'restore'}]);$('#stage-filter').value='draft';renderList();return;
case 'export':download(exportDoc(project),project.title+'-档案备份.json');return;case 'markdown':download(markdown(project),project.title+'-设定阅读版.md','text/markdown;charset=utf-8');return;case 'connect':return connect();
case 'version':{const v=project.versions.find(v=>v.id===id);openDialog(v.name,`<p class="help-note">${date(v.createdAt)} · 保存版本，只读</p><div class="snapshot-content">${v.document.entities.map(e=>`<section><h3>${escape(e.name)}</h3><p>${escape(e.summary)}</p>${e.fields.map(f=>`<h4>${escape(f.label)} ${status(f)}</h4><p>${escape(f.value||'待补充')}</p>`).join('')}</section>`).join('')}</div><div class="row-actions"><button type="button" id="export-version">导出此版本</button><button type="button" id="copy-version">另存为新项目</button></div>`,null);$('#export-version').addEventListener('click',()=>download(exportDoc(v.document),project.title+'-'+v.name+'.json'));$('#copy-version').addEventListener('click',async()=>{try{const value=exportDoc(v.document);value.project.title+=' · '+v.name;const data=await api('/import','POST',value);closeDialog();project=data.project;tab='overview';$('#stage-filter').value='draft';$('#category-filter').value='';$('#project-search').value='';await refresh();render();notice('已另存为新项目，原项目和保存版本仍可回顾。');}catch(e){$('#dialog-error').textContent=e.message;}});return;}
}}
document.addEventListener('click',event=>{const node=event.target.closest('[data-action],[data-tab],[data-project]');if(!node)return;if(node.dataset.project){select(node.dataset.project);return;}if(node.dataset.tab){tab=node.dataset.tab;entityId='';render();return;}Promise.resolve(action(node.dataset.action,node)).catch(fail);});
$('#new-project').addEventListener('click',newProject);for(const id of ['project-search','stage-filter','category-filter'])$('#'+id).addEventListener(id==='project-search'?'input':'change',renderList);
$('#import-project').addEventListener('click',()=>{if(online)$('#import-file').click();else fail(new Error('请先启动本机服务，再导入档案备份。'));});$('#import-file').addEventListener('change',async event=>{try{const file=event.target.files[0];if(!file)return;if(file.size>12*1024*1024)throw new Error('备份文件超过12MB');const data=await api('/import','POST',JSON.parse(await file.text()));project=data.project;tab='overview';$('#stage-filter').value='draft';$('#category-filter').value='';$('#project-search').value='';await refresh();render();notice('备份已作为新的设计项目导入。历史与版本保留在原备份中，本次导入恢复当前设定。');}catch(e){fail(e);}finally{event.target.value='';}});
async function poll(){if(stopped||polling||busy||document.hidden||$('#editor').open)return;polling=true;try{await refresh();const meta=projects.find(p=>p.id===project?.id);if(meta&&meta.revision!==project.revision){const data=await api('/'+project.id);project=data.project;render();notice('已同步其他会话的修改 · '+date(project.updatedAt));}}catch{$('#connection').textContent='连接暂时中断 · 正在重试';}finally{polling=false;}}
const timer=setInterval(poll,5000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)poll();});addEventListener('pagehide',()=>{clearInterval(timer);stopped=true;});addEventListener('pageshow',e=>{if(e.persisted)location.reload();});
refresh().then(()=>{if(projects.length){const requested=new URL(location.href).searchParams.get('project');const latest=projects.find(p=>p.id===requested)||[...projects].sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt))[0];$('#stage-filter').value=latest.stage;return select(latest.id);}}).catch(e=>{online=false;$('#connection').textContent='本机档案库 · 未连接';fail(e);});
})();
